CREATE TABLE tool_registry_snapshots(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE tool_definitions(tool_id TEXT NOT NULL, version TEXT NOT NULL, definition_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(tool_id,version)) STRICT;
CREATE TABLE tool_instances(id TEXT PRIMARY KEY, tool_id TEXT NOT NULL, version TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(tool_id,version) REFERENCES tool_definitions(tool_id,version)) STRICT;
CREATE TABLE tool_batches(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), registry_snapshot_id TEXT NOT NULL REFERENCES tool_registry_snapshots(id), state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE tool_calls(id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES tool_batches(id), ordinal INTEGER NOT NULL CHECK(ordinal>0), operation_id TEXT UNIQUE REFERENCES operations(id), payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(batch_id,ordinal)) STRICT;
CREATE TABLE tool_pins(owner_kind TEXT NOT NULL CHECK(owner_kind IN('workspace','session')), owner_id TEXT NOT NULL, tool_id TEXT NOT NULL, version TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(owner_kind,owner_id,tool_id), FOREIGN KEY(tool_id,version) REFERENCES tool_definitions(tool_id,version)) STRICT;
CREATE TABLE agent_terminals(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), payload TEXT NOT NULL CHECK(json_valid(payload)), output_start INTEGER NOT NULL CHECK(output_start>=0), output_end INTEGER NOT NULL CHECK(output_end>=output_start)) STRICT;
CREATE TABLE terminal_output_segments(terminal_id TEXT NOT NULL REFERENCES agent_terminals(id), start_offset INTEGER NOT NULL, next_offset INTEGER NOT NULL CHECK(next_offset>start_offset), artifact_id TEXT NOT NULL REFERENCES artifacts(id), PRIMARY KEY(terminal_id,start_offset)) STRICT;
CREATE TABLE tool_package_payloads(fingerprint TEXT PRIMARY KEY, descriptor TEXT NOT NULL CHECK(json_valid(descriptor)), ref_count INTEGER NOT NULL DEFAULT 0 CHECK(ref_count>=0)) STRICT;
CREATE TABLE tool_packages(id TEXT PRIMARY KEY, package_key TEXT NOT NULL UNIQUE, current_version TEXT, current_fingerprint TEXT, enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)), revision INTEGER NOT NULL CHECK(revision>0), CHECK((current_version IS NULL)=(current_fingerprint IS NULL)), CHECK(current_fingerprint IS NOT NULL OR enabled=0), FOREIGN KEY(id,current_version,current_fingerprint) REFERENCES tool_package_versions(package_id,version,fingerprint)) STRICT;
CREATE TABLE tool_package_versions(package_id TEXT NOT NULL REFERENCES tool_packages(id), version TEXT NOT NULL, fingerprint TEXT NOT NULL, payload_fingerprint TEXT REFERENCES tool_package_payloads(fingerprint), revision INTEGER NOT NULL CHECK(revision>0), conformance_state TEXT NOT NULL CHECK(conformance_state IN('not_run','running','succeeded','failed','cancelled','interrupted')), conformance TEXT CHECK(conformance IS NULL OR json_valid(conformance)), created_at TEXT NOT NULL, PRIMARY KEY(package_id,version,fingerprint), CHECK(payload_fingerprint IS NULL OR payload_fingerprint=fingerprint)) STRICT;
CREATE TABLE tool_package_files(fingerprint TEXT NOT NULL REFERENCES tool_package_payloads(fingerprint), path TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifacts(id), PRIMARY KEY(fingerprint,path), UNIQUE(fingerprint,artifact_id)) STRICT;
CREATE TABLE tool_package_references(fingerprint TEXT NOT NULL REFERENCES tool_package_payloads(fingerprint), owner_kind TEXT NOT NULL CHECK(owner_kind IN('version','execution')), owner_id TEXT NOT NULL, PRIMARY KEY(fingerprint,owner_kind,owner_id)) STRICT;
CREATE TRIGGER tool_package_reference_added AFTER INSERT ON tool_package_references BEGIN UPDATE tool_package_payloads SET ref_count=ref_count+1 WHERE fingerprint=NEW.fingerprint; END;
CREATE TRIGGER tool_package_reference_removed AFTER DELETE ON tool_package_references BEGIN UPDATE tool_package_payloads SET ref_count=ref_count-1 WHERE fingerprint=OLD.fingerprint; END;
CREATE TABLE tool_package_trust(package_id TEXT PRIMARY KEY, version TEXT NOT NULL, fingerprint TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), granted_at TEXT NOT NULL, FOREIGN KEY(package_id,version,fingerprint) REFERENCES tool_package_versions(package_id,version,fingerprint)) STRICT;
CREATE TABLE tool_package_deletions(id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES tool_packages(id), fingerprint TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('pending','collected')), requested_at TEXT NOT NULL, collected_at TEXT, CHECK((state='collected')=(collected_at IS NOT NULL))) STRICT;
CREATE INDEX tool_package_versions_by_payload ON tool_package_versions(payload_fingerprint);
CREATE INDEX tool_package_references_by_owner ON tool_package_references(owner_kind,owner_id);
CREATE INDEX tool_package_deletions_pending ON tool_package_deletions(state,requested_at);
